import { useEffect, useState } from "react";
import axios from "axios";

function ModifySyllabus() {
  const [syllabusList, setSyllabusList] = useState([]);
  const [editId, setEditId] = useState(null);
  const [moduleName, setModuleName] = useState("");
  const [description, setDescription] = useState("");

  // 🔹 Fetch syllabus
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/VJISS/course_details")
      .then((res) => {
        
        setSyllabusList(res.data);
        console.log("Syllabus data:", res.data.syllabus_courses);
      })
      .catch((err) => {
        console.error("Error fetching syllabus:", err);
      });
  }, []);

  // 🔹 Edit click
  const handleEdit = (item) => {
    setEditId(item.public_id);
    setModuleName(item.module);
    setDescription(item.description);
  };

  // 🔹 Update syllabus
  const handleUpdate = () => {
    axios
      .put(`http://127.0.0.1:8000/VJISS/modify_syllabus/${editId}`, {
        module: moduleName,
        description: description,
      })
      .then(() => {
        alert("Syllabus updated successfully");

        setSyllabusList(
          syllabusList.map((s) =>
            s.public_id === editId
              ? { ...s, module: moduleName, description }
              : s
          )
        );

        setEditId(null);
      })
      .catch((err) => {
        console.error("Update failed:", err);
        alert("Failed to update syllabus");
      });
  };

  return (
    <div>
      <h2>Modify Syllabus</h2>

      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>Course</th>
            <th>Module</th>
            <th>Description</th>
            <th>Action</th>
          </tr>
        </thead>

        <tbody>
          {syllabusList.map((item) => (
            <tr key={item.public_id}>

              <td>{item.syllabus_courses.module}</td>
        
              <td>{item.syllabus_courses.description}</td>
              <td>
                <button onClick={() => handleEdit(item)}>Edit</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {editId && (
        <>
          <h3>Edit Syllabus</h3>

          <input
            type="text"
            value={moduleName}
            onChange={(e) => setModuleName(e.target.value)}
            placeholder="Module Name"
          />

          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description"
          />

          <br />
          <button onClick={handleUpdate}>Update</button>
        </>
      )}
    </div>
  );
}

export default ModifySyllabus;
